PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('worker','admin')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,reward INTEGER NOT NULL CHECK(reward>0),status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','claimed','submitted','approved','rejected')),worker_id TEXT REFERENCES users(id),provider TEXT NOT NULL DEFAULT 'manual',external_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,external_id));
CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,task_id TEXT UNIQUE NOT NULL REFERENCES tasks(id),worker_id TEXT NOT NULL REFERENCES users(id),content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),review_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS withdrawals(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),destination TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','paid','rejected')),reference TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,amount INTEGER NOT NULL,task_id TEXT REFERENCES tasks(id),withdrawal_id TEXT REFERENCES withdrawals(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS one_task_credit ON ledger(task_id) WHERE kind='earning';
CREATE UNIQUE INDEX IF NOT EXISTS one_withdrawal_refund ON ledger(withdrawal_id) WHERE kind='refund';
CREATE TABLE IF NOT EXISTS moderation(task_id TEXT PRIMARY KEY REFERENCES tasks(id),status TEXT NOT NULL CHECK(status IN ('hold','correction','released','denied')),hold_until INTEGER NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS corrections(task_id TEXT PRIMARY KEY REFERENCES tasks(id),step_id TEXT REFERENCES task_steps(id),note TEXT NOT NULL,pending INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS evidence_history(id TEXT PRIMARY KEY,task_id TEXT REFERENCES tasks(id),step_id TEXT,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leases(task_id TEXT PRIMARY KEY REFERENCES tasks(id),worker_id TEXT REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS task_policies(task_id TEXT PRIMARY KEY REFERENCES tasks(id),start_mode TEXT NOT NULL CHECK(start_mode IN ('on_claim','admin_details')),claim_minutes INTEGER CHECK(claim_minutes IS NULL OR claim_minutes BETWEEN 1 AND 43200),deadline_at INTEGER,supplied_at INTEGER,expiry_action TEXT NOT NULL DEFAULT 'recycle' CHECK(expiry_action IN ('recycle','hold')),public_description INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id),username TEXT UNIQUE NOT NULL,referral_code TEXT UNIQUE NOT NULL,referrer_id TEXT REFERENCES users(id),registered_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS referral_awards(task_id TEXT PRIMARY KEY REFERENCES tasks(id),referrer_id TEXT REFERENCES users(id),worker_id TEXT REFERENCES users(id),usd_micros INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS referral_transfers(user_id TEXT PRIMARY KEY REFERENCES users(id),credited_cents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS paid_dates(withdrawal_id TEXT PRIMARY KEY REFERENCES withdrawals(id),paid_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profile_settings(user_id TEXT PRIMARY KEY REFERENCES users(id),chosen_username INTEGER NOT NULL DEFAULT 0,preferred_currency TEXT NOT NULL DEFAULT 'USD');
CREATE TABLE IF NOT EXISTS referral_links(code TEXT PRIMARY KEY,user_id TEXT UNIQUE NOT NULL REFERENCES users(id));
